'BEGIN',
'   ',
'    execute immediate  ''truncate table NURSE_UNIT_DISP'';',
'    execute immediate  ''truncate table BLDG_DISP'';',
'    execute immediate  ''truncate table FACILITY_DISP'';',
'    execute immediate ''truncate table RCO_DIRECTORY'';',
'    FOR rec IN (SELECT * FROM TEMP_TABLE) LOOP -- loop over each record',
'        -- try find existing record RCO_DIRECTORY_ID',
'        BEGIN',
'            SELECT ID INTO v_rco_directory_id',
'            FROM RCO_DIRECTORY',
'            WHERE DIRECTORY = rec.RCO_DIRECTORY',
'              AND FACILITY_DISP = rec.FACILITY_DISP',
'              AND FACILITY_DESC = rec.FACILITY_DESC',
'            FETCH FIRST 1 ROW ONLY;',
'        EXCEPTION',
'            WHEN NO_DATA_FOUND THEN',
'                INSERT INTO RCO_DIRECTORY (DIRECTORY, FACILITY_DISP, FACILITY_DESC)',
'                VALUES (rec.RCO_DIRECTORY, rec.FACILITY_DISP, rec.FACILITY_DESC)',
'                RETURNING ID INTO v_rco_directory_id;',
'        END;',
'',
'        -- try find existing record FACILITY_DISP_ID',
'        BEGIN',
'            SELECT ID INTO v_facility_disp_id',
'            FROM FACILITY_DISP',
'            WHERE RCO_DIRECTORY_ID = v_rco_directory_id',
'              AND ENCOUNTER_ORG = rec.ENCOUNTER_ORG',
'              AND AFF_FAC_POOL_ALIAS = rec.AFF_FAC_POOL_ALIAS',
'              AND CLUSTER_ = rec.CLUSTER_',
'              AND BLDG_DISP = rec.BLDG_DISP',
'              AND BLDG_DESC = rec.BLDG_DESC',
'            FETCH FIRST 1 ROW ONLY;',
'        EXCEPTION',
'            WHEN NO_DATA_FOUND THEN',
'                INSERT INTO FACILITY_DISP (RCO_DIRECTORY_ID, ENCOUNTER_ORG, AFF_FAC_POOL_ALIAS, CLUSTER_, BLDG_DISP, BLDG_DESC)',
'                VALUES (v_rco_directory_id, rec.ENCOUNTER_ORG, rec.AFF_FAC_POOL_ALIAS, rec.CLUSTER_, rec.BLDG_DISP, rec.BLDG_DESC)',
'                RETURNING ID INTO v_facility_disp_id;',
'        END;',
'',
'        -- try find existing record BLDG_DISP_ID',
'        BEGIN',
'            SELECT ID INTO v_bldg_disp_id',
'            FROM BLDG_DISP',
'            WHERE FACILITY_DISP_ID = v_facility_disp_id',
'              AND NURSE_UNIT_DISP = rec.NURSE_UNIT_DISP',
'              AND NURSE_UNIT_DESC = rec.NURSE_UNIT_DESC',
'              AND NU_OUTBOUND_ALIAS = rec.NU_OUTBOUND_ALIAS',
'            FETCH FIRST 1 ROW ONLY;',
'        EXCEPTION',
'            WHEN NO_DATA_FOUND THEN',
'                INSERT INTO BLDG_DISP (FACILITY_DISP_ID, NURSE_UNIT_DISP, NURSE_UNIT_DESC, NU_OUTBOUND_ALIAS)',
'                VALUES (v_facility_disp_id, rec.NURSE_UNIT_DISP, rec.NURSE_UNIT_DESC, rec.NU_OUTBOUND_ALIAS)',
'                RETURNING ID INTO v_bldg_disp_id;',
'        END;',
'',
'        -- try existing record NURSE_UNIT_DISP_ID ( not required 3589 unique records for this table)',
'        ',
'        BEGIN',
'            SELECT ID INTO v_nurse_unit_disp_id',
'            FROM NURSE_UNIT_DISP',
'            WHERE BLDG_DISP_ID = v_bldg_disp_id',
'              AND PATIENT_TYPE = rec.PATIENT_TYPE',
'              AND PATIENT_TYPE_ALIAS = rec.PATIENT_TYPE_ALIAS',
'              AND MEDICAL_SERVICE = rec.MEDICAL_SERVICE',
'              AND OP_PREFIX = rec.OP_PREFIX',
'              AND AFF_SRVC_POOL_ALIAS = rec.AFF_SRVC_POOL_ALIAS',
'              AND MED_SVC_ALIAS = rec.MED_SVC_ALIAS',
'              AND PATIENT_SERVICE_CODE = rec.PATIENT_SERVICE_CODE',
'              AND PATIENT_SERVICE_DESCRIPTION = rec.PATIENT_SERVICE_DESCRIPTION',
'              AND STATUS = rec.STATUS',
'              AND ADDED_DT = rec.ADDED_DT',
'              AND INACTIVE_DT = rec.INACTIVE_DT',
'            FETCH FIRST 1 ROW ONLY;',
'        EXCEPTION',
'            WHEN NO_DATA_FOUND THEN',
'                INSERT INTO NURSE_UNIT_DISP (BLDG_DISP_ID, PATIENT_TYPE, PATIENT_TYPE_ALIAS, MEDICAL_SERVICE, OP_PREFIX, ',
'                                             AFF_SRVC_POOL_ALIAS, MED_SVC_ALIAS, PATIENT_SERVICE_CODE, PATIENT_SERVICE_DESCRIPTION, ',
'                                             STATUS, ADDED_DT, INACTIVE_DT)',
'                VALUES (v_bldg_disp_id, rec.PATIENT_TYPE, rec.PATIENT_TYPE_ALIAS, rec.MEDICAL_SERVICE, rec.OP_PREFIX, ',
'                        rec.AFF_SRVC_POOL_ALIAS, rec.MED_SVC_ALIAS, rec.PATIENT_SERVICE_CODE, rec.PATIENT_SERVICE_DESCRIPTION, ',
'                        rec.STATUS, rec.ADDED_DT, rec.INACTIVE_DT)',
'                RETURNING ID INTO v_nurse_unit_disp_id;',
'        END;',
'    END LOOP;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(30215966012268047)
,p_internal_uid=>11273827528015435
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(30216820429268051)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
